templates.code:
- id: app
  uses: actions/create-github-app-token@v3
  with: { client-id: "${{ vars.{var_app} }}", private-key: "${{ secrets.{secreto_app} }}" }
- env: { IMG: "{repo}:{tag}@${{ needs.{job_imagen}.outputs.digest }}" }
  run: sed -i "s|{repo}[:@].*$|$IMG|" {manifest}
- uses: peter-evans/create-pull-request@{sha_action}
  with: { token: "${{ steps.app.outputs.token }}", branch: deploy/{servicio}, title: "deploy: {servicio} {tag}" }

apiVersion: argoproj.io/v1alpha1
kind: Application
metadata: { name: {app}, namespace: argocd }
spec:
  project: default
  source: { repoURL: {repo_git}, targetRevision: main, path: {carpeta} }
  destination: { server: https://kubernetes.default.svc, namespace: {ns} }
  syncPolicy: { automated: { prune: true, selfHeal: true } }

deploy:
  needs: {job_imagen}
  environment: {entorno}
  concurrency: { group: deploy-{servicio}-{entorno}, cancel-in-progress: false }
  steps:  # antes: el rol de deploy por OIDC (sección 8), aws eks update-kubeconfig y un kubectl de la versión del cluster
    - run: kubectl -n {ns} set image deployment/{servicio} {contenedor}={registry}/{repo}@{digest} && kubectl -n {ns} rollout status deployment/{servicio} --timeout={plazo}

git switch -c revert-deploy origin/main
git revert -m 1 {sha_merge}     # PR con merge commit; con squash: git revert {sha}
git push -u origin revert-deploy  # PR → merge → Argo CD aplica la versión anterior

git clone --branch {rama} {url_repo} /tmp/ci && cd /tmp/ci/{dir}
python{version} -m venv .venv && . .venv/bin/activate
pip install -r requirements-dev.txt && pytest

git bisect start {malo} {bueno}
git bisect run {prueba}
git bisect reset
